scripts.script:
if (args.attacker && Macros.checkStance(actor, args)) {
    const effectData = thisItem.effects.getName("残气").toObject();
    effectData.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(args.attacker, effectData);
    ui.notifications.info(`${actor.name} 的架招使 ${args.attacker.name} 沾染了残气！`);
}

if (args.isBroken) {
    await game.xjzl.api.effects.addEffect(args.target, "root");
    ui.notifications.info(`${args.target.name} 被禁足！(击退和障碍物判定请手动处理)`);
}

const lvl = Math.max(1, args.baseData.level);
output.feint += (lvl - 1) * 1;
    args.output.feintBonusDesc.push("沽名倒海升级加成" + (lvl - 1) * 1);

if (args.isHit) {
    const effectData = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "fushen"));
    effectData.duration = { rounds: 2 };
    await game.xjzl.api.effects.addEffect(args.target, effectData);
}

// 尝试在计算阶段预览伤害（依赖当前选中目标）
const targets = Array.from(game.user.targets);
if (targets.length === 1) {
    const target = targets[0].actor;
    const effect = target.effects.find(e => e.getFlag("xjzl-system", "slug") === "canqi");
    if (effect) {
        const stacks = effect.getFlag("xjzl-system", "stacks") || 1;
        output.damage += stacks * 5;
        output.bonusDesc.push(`吞噬残气(${stacks}层): +${stacks * 5}`);
    }
}

const effect = args.target.effects.find(e => e.getFlag("xjzl-system", "slug") === "canqi");
if (effect) {
    await effect.delete();
    ui.notifications.info("已吞噬目标身上的残气。");
}

if (args.isDead) {
    await actor.changeResources({ "system.resources.rage.value": actor.system.resources.rage.value + 2 }, { cause: "script", sourceActor: actor, item: thisItem instanceof Item ? thisItem : (args.item || null), move: typeof move !== "undefined" ? move : (args.move || null) });
    ui.notifications.info("击杀敌人，怒气+2");
}

const ring = actor.items.find(i => i.name.includes("枫桦戒") && i.system.equipped);
if (!ring) return ui.notifications.warn("未装备枫桦戒！");

const effectData = thisItem.effects.getName("气刃").toObject();
effectData.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, effectData);

// 瞬发处理
args.flags.autoApplied = true;
ui.notifications.info("已化气为刃 (移动速度+2)。请手动创建临时武器以体现武器属性。");

if (!args.attacker || !Macros.checkStance(actor, args)) return;

let stacks = 1;
const qiren = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "qiren");

if (qiren) {
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "消耗气刃" },
        content: "<p>格挡成功！是否消耗【气刃】为目标额外添加一层【失准】？</p>",
        yes: { label: "消耗气刃", icon: "fas fa-check" },
        no: { label: "保留", icon: "fas fa-times" }
    });

    if (confirm) {
        await qiren.delete();
        stacks = 2;
        actor.showFloatyText("气刃消散！", {fill: "#00ffff"});
    }
}

const effectData = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "shizhun"));
if (effectData) {
    effectData.duration = { rounds: 99 };
    for(let i=0; i<stacks; i++) {
        await game.xjzl.api.effects.addEffect(args.attacker, effectData);
    }
}

if (actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "qiren")) {
    output.damage += 10;
    output.bonusDesc.push("气刃加成: +10");
}

if (args.isHit) {
    if (!args.target.system.martial.stanceActive) {
        ui.notifications.info(`${args.target.name} 被击飞 1 米(手动移动)。`);
    }
    if (args.isManual) {
         await game.xjzl.api.effects.addEffect(args.target, "prone");
         ui.notifications.info("判定为追击半空敌人，目标被击倒。");
    }
}

const qiren = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "qiren");
if (qiren) {
    await qiren.delete();
    ui.notifications.info("气刃碎裂！请手动对周围敌人应用伤害。");
}
if (args.isDead) {
    ui.notifications.info("击杀敌人，获得一个次要动作！");
}

const ring = actor.items.find(i => i.name.includes("枫桦戒") && i.system.equipped);
if (!ring) return ui.notifications.warn("未装备枫桦戒！");
const effectData = thisItem.effects.getName("气枝").toObject();
effectData.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, effectData);

// 瞬发处理
args.flags.autoApplied = true;
ui.notifications.info("已化气为枝 (距离+3请手动留意)。");

if (args.isHit) {
    let rounds = 1;
    if (actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "qizhi")) rounds = 2;

    const effectData = thisItem.effects.getName("红尘").toObject();
    effectData.origin = thisItem.uuid;
    effectData.duration = { rounds: rounds };

    await game.xjzl.api.effects.addEffect(args.target, effectData);
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const effectData = thisItem.effects.getName("断尘").toObject();
    effectData.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(args.target, effectData);
    ui.notifications.info("目标陷入断尘。");
}

if (args.isHit) {
    const hasDuan = args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "duanchen");
    const hasHong = args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "hongchen");
    if (hasDuan && hasHong) {
        await game.xjzl.api.effects.addEffect(args.target, "rage");
        ui.notifications.info(`${args.target.name} 走火入魔！`);
    }
}

const qizhi = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "qizhi");
if (qizhi) {
    await qizhi.delete();
    // 给自己加红尘
    const effectData = thisItem.effects.getName("红尘").toObject();
    effectData.origin = thisItem.uuid;
    effectData.duration = { rounds: 2 };
    await game.xjzl.api.effects.addEffect(actor, effectData);
    ui.notifications.info("气枝化为红尘缠身。");
}

const ring = actor.items.find(i => i.name.includes("枫桦戒") && i.system.equipped);
if (!ring) return ui.notifications.warn("未装备枫桦戒！");
const effectData = thisItem.effects.getName("气箫").toObject();
effectData.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, effectData);

// 瞬发处理
args.flags.autoApplied = true;
ui.notifications.info("已化气为箫 (演奏+2)。");

if (args.attacker && Macros.checkStance(actor, args)) {
    // 正确获取当前架招的等级 (不能用 args.move)
    const stanceId = actor.system.martial.stance;
    const stanceMove = thisItem.system.moves.find(m => m.id === stanceId);
    const lvl = Math.max(1, stanceMove?.computedLevel || 1);

    const yanzou = args.attacker.system.arts?.yanzou?.total || 0;
    const reqLevel = 1 + lvl; // 1级需2，2级需3

    if (yanzou < reqLevel) {
        // 1. 施加耳鸣
        const deafData = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "deaf"));
        if (deafData) {
            deafData.duration = { rounds: 1 };
            await game.xjzl.api.effects.addEffect(args.attacker, deafData);
        }

        // 2. 构建基础聊天卡片内容 (增加 margin-left 和 padding-left 防止边框遮挡)
        let cardContent = `
        <div class="xjzl-chat-card">
            <div style="padding:5px; padding-left:8px; border-left:4px solid #8e44ad; background:rgba(142,68,173,0.1); margin-left:2px;">
                <div style="font-weight:bold; color:#8e44ad;">
                    <i class="fas fa-music"></i> 曲高和寡
                </div>
                <div style="font-size:0.9em; margin-top:4px; color:#555;">
                    <b>${args.attacker.name}</b> 演奏造诣不足 (当前${yanzou}，需${reqLevel})，陷入 <b>[耳鸣]</b> 1 回合。
                </div>
            </div>`;

        // 3. 追击判定 (气箫)
        const qixiao = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "qixiao");
        if (qixiao) {
            cardContent += `
            <div style="padding:5px; padding-left:8px; border-left:4px solid #d35400; background:rgba(211,84,0,0.1); margin-left:2px; margin-top:5px;">
                <div style="font-weight:bold; color:#d35400;">
                    <i class="fas fa-bolt"></i> 气箫共鸣
                </div>
                <div style="font-size:0.9em; margin-top:4px; color:#555;">
                    触发追击！请手动<b>无消耗</b>施展【知音难觅】。
                </div>
            </div>`;

            // 移除气箫
            await game.xjzl.api.effects.removeEffect(actor, "qixiao", 1);
        }

        cardContent += `</div>`;

        // 4. 发送公共聊天卡片
        ChatMessage.create({
            content: cardContent,
            speaker: ChatMessage.getSpeaker({actor: actor})
        });
    }
}

if (actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "qixiao")) {
    output.damage += 10;
    output.bonusDesc.push("气箫加成: +10");
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const effectData = thisItem.effects.getName("惭愧").toObject();
    effectData.origin = thisItem.uuid;
    effectData.description = `无法攻击 ${actor.name}`;
    await game.xjzl.api.effects.addEffect(args.target, effectData);
}

if (args.isHit && actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "qixiao")) {
    const myArt = actor.system.arts.yanzou.total || 0;
    ui.notifications.info(`请手动进行演奏对抗 (我方演奏: ${myArt})。若对方失败，请手动施加封招。`);
}

const ring = actor.items.find(i => i.name.includes("枫桦戒") && i.system.equipped);
if (!ring) return ui.notifications.warn("未装备枫桦戒，无法施展！");

const effectData = thisItem.effects.getName("气弓").toObject();
delete effectData._id;
effectData.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, effectData);

args.flags.autoApplied = true;
ui.notifications.info("已化气为弓 (闪避+4)。");

const qigong = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "qigong");
if (qigong) {
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "漫天飞羽" },
        content: "<p>是否消耗【气弓】使本次攻击对所有命中目标施加【禁足】？</p>",
        yes: { label: "消耗气弓", icon: "fas fa-check" },
        no: { label: "保留", icon: "fas fa-times" }
    });

    if (confirm) {
        await qigong.delete();
        args.flags.qiBowConsumed = true; 
        actor.showFloatyText("气弓消散！", {fill: "#ffffff"});
    }
}

if (args.isHit && args.flags.qiBowConsumed) {
    const rootEff = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "root"));
    if (rootEff) {
        rootEff.duration = { rounds: 1 };
        await game.xjzl.api.effects.addEffect(args.target, rootEff);
    }
}

const qigong = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "qigong");
if (qigong) {
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "秋风送寒" },
        content: "<p>是否决定消耗【气弓】使本次招式的虚招值增加？</p>",
        yes: { label: "决定消耗", icon: "fas fa-check" },
        no: { label: "保留", icon: "fas fa-times" }
    });

    if (confirm) {
        await qigong.delete();
        const lvl = Math.max(1, move.computedLevel || 1);
        args.flags.bonusFeint += lvl;
        actor.showFloatyText("气弓消散！", {fill: "#ffffff"});
        ui.notifications.info(`已消耗气弓，虚招值 +${lvl}`);
    }
}

if (args.isBroken) {
    const effData = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "unstable"));
    if (effData) {
        effData.duration = { rounds: 3 };
        await game.xjzl.api.effects.addEffect(args.target, effData);
    }
}

const qigong = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "qigong");
if (qigong) {
    const lvl = Math.max(1, move.computedLevel || 1);
    const critBonus = lvl;
    args.flags.critThresholdMod += critBonus;
    ui.notifications.info(`气弓加持: 暴击门槛 -${critBonus}`);
}

if (args.isHit) {
    let rounds = 1;
    if (actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "qigong")) {
        rounds = 3;
    }

    const effectData = foundry.utils.deepClone(CONFIG.statusEffects.find(e => e.id === "fushen"));
    if (effectData) {
        effectData.duration = { rounds: rounds };
        await game.xjzl.api.effects.addEffect(args.target, effectData);
    }
}

if (args.attacker && Macros.checkStance(actor, args)) {
    const effectData = thisItem.effects.getName("悟情").toObject();
    delete effectData._id;
    effectData.origin = thisItem.uuid;

    // 动态持续回合：1级1回合，2级2回合...
    const lvl = Math.max(1, move.computedLevel || 1);
    effectData.duration = { rounds: lvl };

    await game.xjzl.api.effects.addEffect(actor, effectData);
}

if (args.isHit && args.target) {
    // 修正后的性格获取函数：直接读性格物品的名字
    const getP = (act) => {
        if (!act) return "";
        if (act.itemTypes?.personality?.length > 0) {
            return act.itemTypes.personality[0].name;
        }
        return act.system?.info?.personality || "";
    };

    const targetP = getP(args.target);
    const myP = getP(actor);

    // 1. 发送窥探性格的提示卡片
    const pName = targetP ? targetP : "无明显性格";
    ChatMessage.create({
        speaker: ChatMessage.getSpeaker({actor: actor}),
        content: `<div class="xjzl-chat-card" style="padding: 4px 8px; margin-left: 4px; border-left: 4px solid #2980b9; background: rgba(41, 128, 185, 0.1);">
            <div style="font-size: 0.9em; color: #2c3e50;"><i class="fas fa-eye"></i> 窥探到目标性格：<b>${pName}</b></div>
        </div>`
    });

    // 2. 校验共鸣 (确保两者都不为空且相等)
    if (targetP && myP && targetP === myP) {
        // 扣除怒气
        const currentRage = args.target.system.resources.rage.value;
        if (currentRage > 0) {
            await args.target.changeResources({ "system.resources.rage.value": currentRage - 1 }, { cause: "script", sourceActor: actor, target: args.target, item: thisItem instanceof Item ? thisItem : (args.item || null), move: typeof move !== "undefined" ? move : (args.move || null) });
        }

        // 施加迟滞 1回合
        const chizhiConfig = CONFIG.statusEffects.find(e => e.id === "chizhi");
        if (chizhiConfig) {
            const chizhiData = foundry.utils.deepClone(chizhiConfig);
            chizhiData.duration = { rounds: 1 };
            await game.xjzl.api.effects.addEffect(args.target, chizhiData);
        }

        actor.showFloatyText("性格共鸣！", { fill: "#e056fd" });
    }
}

if (args.isHit && args.target) {
    const getP = (act) => {
        if (!act) return "";
        if (act.itemTypes?.personality?.length > 0) {
            return act.itemTypes.personality[0].name;
        }
        return act.system?.info?.personality || "";
    };

    const targetP = getP(args.target);
    const myP = getP(actor);

    if (targetP && myP && targetP === myP) {
        const msg = `
            <div class="xjzl-chat-card" style="margin-left: 4px; padding: 4px 8px; border-left: 4px solid #8e44ad; background: rgba(142, 68, 173, 0.1);">
                <div style="font-weight: bold; color: #8e44ad;"><i class="fas fa-people-arrows"></i> 性格共鸣触发！</div>
                <div style="font-size: 0.9em; margin-top: 4px; color: #555;">
                    双方性格同为 <b>${myP}</b>。<br>
                    <hr style="margin:4px 0;">
                    请手动发起一个【受该性格加成的属性技能】对抗。<br>
                    若获胜，请手动对目标造成 <b>技能等级 × 10</b> 点气血流失。
                </div>
            </div>`;
        ChatMessage.create({
            speaker: ChatMessage.getSpeaker({actor: actor}),
            content: msg
        });
    }
}

const wuqing = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuqing");
const lvl = Math.max(1, move.computedLevel || 1);

if (wuqing) {
    // 移除悟情
    await game.xjzl.api.effects.removeEffect(actor, "wuqing", 1);

    // 获取并修改悟
    const wuEffect = thisItem.effects.getName("悟").toObject();
    delete wuEffect._id;
    wuEffect.origin = thisItem.uuid;
    wuEffect.duration = { rounds: 99 }; // 持续到脱战

    // 动态计算悟性加成: 等级 * 5
    const bonus = lvl * 5;
    const wuxingChange = wuEffect.changes.find(c => c.key === "system.stats.wuxing.mod");
    if (wuxingChange) {
        wuxingChange.value = String(bonus);
    }
    wuEffect.description += ` (当前提供悟性 +${bonus})`;

    await game.xjzl.api.effects.addEffect(actor, wuEffect);
    actor.showFloatyText("大彻大悟！", { fill: "#f1c40f" });
} else {
    // 获得悟情
    const effectData = thisItem.effects.getName("悟情").toObject();
    delete effectData._id;
    effectData.origin = thisItem.uuid;
    effectData.duration = { rounds: 99 }; // 持续到脱战
    await game.xjzl.api.effects.addEffect(actor, effectData);
    actor.showFloatyText("获得悟情", { fill: "#e74c3c" });
}

// 瞬发处理
args.flags.autoApplied = true;

const wuxing = actor.system.stats.wuxing.total || 0;
args.output.damage += wuxing;
args.output.bonusDesc.push(`悟性增伤 (+${wuxing})`);

const weapon = actor.itemTypes.weapon.find(w => w.system.equipped && w.system.type === "hidden");
if (weapon && weapon.system.damage === 0) {
    args.flags.critThresholdMod += 1;
    ui.notifications.info("叶片攻击：暴击门槛-1，距离翻倍(请自行确认距离)");
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    await game.xjzl.api.effects.addEffect(args.target, "bleed_stack");
}

const moveData = args.move;
const lvl = Math.max(1, moveData?.computedLevel || 1);
const bonus = lvl;
const artKeys = Object.keys(CONFIG.XJZL.arts);
for (const key of artKeys) {
    if (system.arts && system.arts[key]) {
        system.arts[key].checkMod = (system.arts[key].checkMod || 0) + bonus;
    }
}

const moveData = args.move;
const lvl = Math.max(1, moveData?.computedLevel || 1);
const bonus = lvl;
const skills = ['dianxue', 'zhuizong', 'tancha', 'dongcha'];
for (const sk of skills) {
    if (system.skills[sk]) {
        system.skills[sk].mod = (system.skills[sk].mod || 0) + bonus;
    }
}

if (!args.attacker) return;
const originItem = await fromUuid(thisEffect.origin);
if (!originItem) return;
const sourceEffect = originItem.effects.getName('残气');
if (!sourceEffect) return ui.notifications.warn('特效模板[残气]缺失');
const effectData = sourceEffect.toObject();
delete effectData._id;
effectData.origin = originItem.uuid;
effectData.disabled = false;
await game.xjzl.api.effects.addEffect(args.attacker, effectData);
if (actor.token?.object) {
    actor.showFloatyText('所见所闻', {
        fill: '#00FFFF', stroke: '#000000', strokeThickness: 4
    });
}

const moveData = args.move;
const lvl = Math.max(1, moveData?.computedLevel || 1);
const bonusPerType = 10 + (lvl - 1) * 10;
let count = 0;
const ranks = system.combat.weaponRanks || {};
for (const key of Object.keys(ranks)) {
    if (ranks[key].total >= 8) {
        count++;
    }
}
if (count > 0) {
    const totalBonus = count * bonusPerType;
    system.resources.hp.bonus = (system.resources.hp.bonus || 0) + totalBonus;
    system.resources.mp.bonus = (system.resources.mp.bonus || 0) + totalBonus;
}
